tab('Table 1.2: Project work plan',['Stage','Activity','Review gate'],[('Requirements','Define audience, scope and rules','Requirements table'),('Interface/simulator','Build UI and deterministic evaluation','Walkthrough'),('Persistence/API','Store rules and expose endpoints','CRUD check'),('Guarded backend','Add validation and safety gates','Unit tests'),('VM validation','Isolated client/server test','Captured evidence'),('Reporting','Document findings and limits','Template review')])
